<script setup lang="ts">
import {locale,tr} from '../lib/i18n'
import { computed, ref, onMounted, onUnmounted, watch, nextTick } from 'vue'
import { api, ApiError } from '../lib/api'
import ChatFlow from './ChatFlow.vue'
import ReplyTopup from './ReplyTopup.vue'
import { asset } from '../lib/assets'
type Conversation={id:string;peerId?:string;displayName:string;avatar?:string;remark?:string;pinned:boolean;muted:boolean;hidden:boolean;following:boolean;unreadCount:number;status:string;lastMessage?:string;updatedAt?:string}
type Message={id:string;content:string;kind:string;createdAt:string;senderId?:string}
type Pending={id:string;conversationId:string}
const props=defineProps<{token:string;userId:string}>(),emit=defineEmits<{close:[];signin:[];profile:[]}>()
const tab=ref('messages'),hidden=ref(false),items=ref<Conversation[]>([]),pending=ref<Pending[]>([]),query=ref(''),draftQuery=ref(''),drawer=ref(false),options=ref<Conversation>(),detail=ref<Conversation>(),messages=ref<Message[]>([]),remark=ref(''),error=ref(''),loading=ref(false),busy=ref(false),hasMore=ref(false),offset=ref(0),collected=ref(0),payment=ref(false),cost=ref(0),balance=ref(0),free=ref(0),receipt=ref<Pending>(),key=ref(''),messageOffset=ref(0),moreMessages=ref(false)
const topupNotice=ref('')
const collectedConversation=ref('')
const collectedCost=ref(0),topup=ref(false),replyState=ref(''),walletReady=ref(false)
const blockedScreen=ref(false),blocks=ref<{userId:string;createdAt:string}[]>([]),unblock=ref(''),blockNames=ref<Conversation[]>([])
async function loadBlocks(){blockedScreen.value=true;drawer.value=false;loading.value=true;error.value='';try{const [r,all]=await Promise.all([request<{items:{userId:string;createdAt:string}[]}>('/blocks'),listAll()]);blocks.value=r.items;blockNames.value=all}catch(e){fail(e)}finally{loading.value=false}}
function blockedName(id:string){return blockNames.value.find(c=>c.peerId===id)?.displayName||'MauGo member'}
async function removeBlock(){if(busy.value)return;busy.value=true;error.value='';try{await request(`/blocks/${unblock.value}`,'DELETE');unblock.value='';await loadBlocks();await load()}catch(e){fail(e)}finally{busy.value=false}}
async function refreshWallet(){const w=await request<{diamonds:number;freeRemaining:number;paidCost:number}>('/wallet');balance.value=w.diamonds;free.value=w.freeRemaining;cost.value=free.value>0?0:w.paidCost;walletReady.value=true}
async function returnToReply(funded=false){topup.value=false;payment.value=true;error.value='';topupNotice.value=funded?'Diamonds added. Confirm collection to continue.':'Top-up closed. No reply collected; selection saved.';try{await refreshWallet();replyState.value=balance.value<cost.value?'reply-shortage':'reply-payment'}catch(e){fail(e)}}
const notificationOff=ref(typeof Notification==='undefined'||Notification.permission!=='granted'),dismissed=ref(sessionStorage.getItem('maugo-inbox-prompt')==='dismissed')
let generation=0,searchGeneration=0
const shown=computed(()=>items.value.slice().sort((a,b)=>Number(b.pinned)-Number(a.pinned)))
const state=computed(()=>unblock.value?'unblock-confirm':blockedScreen.value?(blocks.value.length?'blocked-list':'blocked-empty'):drawer.value?'inbox-drawer':options.value?'inbox-options':hidden.value?(shown.value.length?'inbox-hidden':'inbox-hidden-empty'):query.value?(shown.value.length?'inbox-search':'inbox-search-empty'):tab.value==='friends'?(shown.value.length?'inbox-friends':'inbox-friends-empty'):pending.value.length?(collected.value?'inbox-collected-one':'inbox-pending'):collected.value?'inbox-collected-all':shown.value.some(i=>i.pinned&&i.muted)?'inbox-pinned':notificationOff.value&&!dismissed.value?'inbox-notifications-off':!shown.value.length?'inbox-empty':shown.value.every(i=>i.status==='waiting')?'inbox-waiting':shown.value.some(i=>i.unreadCount)?'inbox-unread':'inbox-read')
async function request<T>(path:string,method='GET',body?:object,extra?:Record<string,string>){return api<T>(path,{method,headers:{Authorization:`Bearer ${props.token}`,...(body?{'Content-Type':'application/json'}:{}),...extra},...(body?{body:JSON.stringify(body)}:{})})}
function fail(e:unknown){error.value=e instanceof ApiError&&e.status===404?'Conversation API is unavailable. Please try again later.':(e as Error).message}
async function listAll(){let all:Conversation[]=[];for(let n=0;;n+=50){const r=await request<{items:Conversation[];hasMore?:boolean}>(`/conversations?tab=messages&hidden=false&limit=50&offset=${n}`);all.push(...r.items);if(!r.hasMore&&r.items.length<50)break}return all}
async function load(append=false){const g=++generation;loading.value=true;error.value='';if(!props.token){error.value='Sign in to meet your replies.';loading.value=false;return}try{const n=append?offset.value:0;const r=await request<{items:Conversation[];hasMore?:boolean}>(`/conversations?${new URLSearchParams({tab:tab.value,hidden:String(hidden.value),limit:'20',offset:String(n)})}`);if(g!==generation)return;items.value=append?[...items.value,...r.items]:r.items;offset.value=n+r.items.length;hasMore.value=r.hasMore??r.items.length===20;
if(!append){const all=await listAll();const queues=await Promise.all(all.map(async c=>{const replies:Pending[]=[];for(let offset=0;;offset+=100){const q=await request<{items:{id:string}[];hasMore?:boolean}>(`/conversations/${c.id}/replies/pending?limit=100&offset=${offset}`);replies.push(...q.items.map(r=>({id:r.id,conversationId:c.id})));if(!q.hasMore)break}return replies}));if(g!==generation)return;pending.value=queues.flat();if(query.value)await search();await refreshWallet()}
}catch(e){if(g===generation)fail(e)}finally{if(g===generation)loading.value=false}}
async function search(){generation++;const g=++searchGeneration;query.value=draftQuery.value.trim();drawer.value=false;if(!query.value){await load();return}loading.value=true;error.value='';try{const all=await listAll();const matches=await Promise.all(all.map(async c=>{const r=await request<{items:Message[]}>(`/conversations/${c.id}/messages?${new URLSearchParams({search:query.value,markRead:'false',limit:'20',offset:'0'})}`);return r.items.length||`${c.displayName} ${c.remark||''}`.toLowerCase().includes(query.value.toLowerCase())?c:undefined}));if(g===searchGeneration){items.value=matches.filter((x):x is Conversation=>!!x).filter(c=>tab.value!=='friends'||c.following);hasMore.value=false}}catch(e){if(g===searchGeneration)fail(e)}finally{if(g===searchGeneration)loading.value=false}}
async function patch(c:Conversation,body:Partial<Conversation>){if(busy.value)return;busy.value=true;error.value='';try{const updated=await request<Conversation>(`/conversations/${c.id}`,'PATCH',body);Object.assign(c,updated);options.value=undefined;await load()}catch(e){fail(e)}finally{busy.value=false}}
async function open(c:Conversation,append=false){if(loading.value)return;loading.value=true;error.value='';try{const n=append?messageOffset.value:0;const r=await request<{items:Message[];hasMore?:boolean}>(`/conversations/${c.id}/messages?markRead=true&limit=20&offset=${n}`);messages.value=append?[...messages.value,...r.items]:r.items;messageOffset.value=n+r.items.length;moreMessages.value=r.hasMore??r.items.length===20;detail.value=c;c.unreadCount=0}catch(e){fail(e)}finally{loading.value=false}}
async function prepare(){topupNotice.value='';if(busy.value||!pending.value.length)return;const next=detail.value?pending.value.find(r=>r.conversationId===detail.value!.id):pending.value[0];if(!next)return;busy.value=true;error.value='';try{await refreshWallet();if(receipt.value?.id!==next.id){receipt.value=next;key.value=crypto.randomUUID()}payment.value=true;replyState.value=cost.value?(balance.value<cost.value?'reply-shortage':'reply-payment'):'reply-last-free'}catch(e){fail(e)}finally{busy.value=false}}
async function collect(){if(busy.value||!receipt.value)return;busy.value=true;error.value='';try{const r=await request<{state:string;cost:number}>(`/conversations/${receipt.value.conversationId}/replies/${receipt.value.id}/collect`,'POST',{confirmPaid:cost.value>0},{'Idempotency-Key':key.value});if(r.state==='confirmation-required'){cost.value=r.cost;replyState.value=balance.value<cost.value?'reply-shortage':'reply-payment';return}if(r.state!=='collected')throw Error('Reply was not collected. Please retry.');pending.value=pending.value.filter(p=>p.id!==receipt.value!.id);collected.value++;collectedConversation.value=receipt.value.conversationId;collectedCost.value=r.cost;replyState.value='reply-paid';payment.value=false;receipt.value=undefined;await load();if(detail.value){const updated=items.value.find(c=>c.id===detail.value!.id);if(updated)Object.assign(detail.value,updated)}}catch(e){if(e instanceof ApiError&&e.status===402){await refreshWallet();replyState.value='reply-shortage'}else fail(e)}finally{busy.value=false}}
async function readAll(){drawer.value=false;error.value='';try{for(const c of await listAll())await request(`/conversations/${c.id}/messages?markRead=true&limit=1&offset=0`);await load()}catch(e){fail(e)}}
function dismiss(){dismissed.value=true;sessionStorage.setItem('maugo-inbox-prompt','dismissed')}
async function enable(){if(typeof Notification==='undefined'){error.value='Notifications are unavailable on this device.';return}notificationOff.value=await Notification.requestPermission()!=='granted'}
function closeOverlay(){if(busy.value)return;if(payment.value)replyState.value='reply-cancelled';payment.value=false;options.value=undefined;drawer.value=false}
let restoreFocus:HTMLElement|null=null
watch(()=>drawer.value||!!options.value||payment.value,async active=>{if(active){restoreFocus=document.activeElement===document.body?document.querySelector<HTMLElement>(payment.value?'#collect-replies':'#inbox-menu'):document.activeElement as HTMLElement;await nextTick();document.querySelector<HTMLElement>('.inbox-flow [role="dialog"] button,.inbox-flow [role="dialog"] input')?.focus()}else{await nextTick();restoreFocus?.focus()}})
function escape(e:KeyboardEvent){
 if(e.key==='Escape'){if(drawer.value||options.value||payment.value)closeOverlay();else detail.value=undefined}
 if(e.key==='Tab'&&(drawer.value||options.value||payment.value)){const dialog=document.querySelector('.inbox-flow [role="dialog"]');const controls=Array.from(dialog?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),a[href]')||[]).filter(el=>el.getClientRects().length);const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}
}
watch([tab,hidden],()=>{searchGeneration++;query.value='';draftQuery.value='';void load()})
onMounted(()=>{void load();document.addEventListener('keydown',escape)})
onUnmounted(()=>{generation++;searchGeneration++;document.removeEventListener('keydown',escape)})
</script>
<template>
<section class="inbox-flow inbox-page" :data-reply-state="replyState||(walletReady&&free===1?'reply-last-free':'')" :data-state="state" :aria-busy="loading||busy">
<img class="inbox-statusbar" :src="asset('09-navigation-system/status-bar-light-content')" alt="" aria-hidden="true"><header v-if="!detail&&!blockedScreen" class="inbox-top"><div class="inbox-heading-tabs"><button v-if="hidden" :aria-label="tr('Back to messages')" @click="hidden=false">‹</button><template v-if="!hidden"><button id="tab-messages" :aria-pressed="tab==='messages'" @click="tab='messages'">{{tr("Messages")}}</button><button id="tab-friends" :aria-pressed="tab==='friends'" @click="tab='friends'">{{tr("Following")}}</button></template><h1 v-else>{{tr("Hidden conversations")}}</h1></div><button id="inbox-menu" class="inbox-menu-button" :aria-label="tr('Inbox menu')" @click="drawer=true"><i></i><i></i><i></i></button></header>
<p v-if="error" class="inbox-error" role="alert">{{tr(error)}} <button v-if="!token" @click="emit('signin')">{{tr("Sign in")}}</button><button v-else :disabled="busy||loading" @click="detail?open(detail):load()">{{tr("Retry")}}</button></p>
<section v-if="blockedScreen" class="d3-blocked"><header><button :aria-label="tr('Back to messages')" @click="blockedScreen=false">‹</button><h1>{{tr("Blocked people")}}</h1><span></span></header><p v-if="loading" role="status">{{tr("Loading…")}}</p><TransitionGroup name="conversation"><div v-for="b in blocks" :key="b.userId" class="d3-blocked-row"><img :src="asset('05-avatars/avatar-placeholder')" alt=""><span>{{blockedName(b.userId)}}</span><button class="outline-button" :data-unblock="b.userId" @click="unblock=b.userId">{{tr("Unblock")}}</button></div></TransitionGroup><div v-if="!loading&&!blocks.length&&!error" class="feature-empty"><img :src="asset('11-symbol-icons/icon-block-40-d6a491')" alt=""><h3>{{tr("No one is blocked.")}}</h3></div></section>
<Transition name="inbox-sheet"><div v-if="unblock" class="inbox-veil"><section class="inbox-sheet" role="dialog" aria-modal="true" :aria-label="tr('Unblock this person?')"><h2>{{tr("Unblock this person?")}}</h2><p>{{tr("You can continue this conversation.")}}</p><button id="confirm-unblock" class="primary" :disabled="busy" @click="removeBlock">{{tr(busy?'Saving…':'Unblock')}}</button><button class="text-button" :disabled="busy" @click="unblock=''">{{tr("Cancel")}}</button><p v-if="error" role="alert">{{tr(error)}}</p></section></div></Transition>
<div v-show="!blockedScreen" class="inbox-body" :inert="drawer||!!options||payment||topup">
<template v-if="!detail">
<Transition name="collect-strip"><button v-if="pending.length&&tab==='messages'&&!hidden" id="collect-replies" class="collect-replies" :disabled="busy||loading" @click="prepare"><span class="collect-symbol"><img :src="asset('08-interface-icons/icon-mail-lime-22')" alt=""></span><span class="collect-copy"><strong>{{tr("Collect replies")}}</strong><small>{{tr(walletReady?(free?`${free} free today`:`${cost} diamonds per reply`):'Checking daily allowance…')}}</small></span><span class="reply-avatar-stack"><img v-for="r in pending.slice(0,3)" :key="r.id" :src="items.find(c=>c.id===r.conversationId)?.avatar||asset('01-brand-scenes/envelope-avatar')" alt=""><i>•••</i></span><b :key="pending.length">{{pending.length}}</b><span class="collect-chevron">›</span></button></Transition>
<p v-if="loading" class="inbox-status" role="status">{{tr("Little birds are on their way…")}}</p>
<TransitionGroup name="conversation" tag="div" class="inbox-conversations"><div v-for="c in shown" :key="c.id" class="chat-row-wrap" :class="{'is-pinned':c.pinned,'reply-collected':c.id===collectedConversation}" @animationend="collectedConversation=''"><button class="chat-row" :disabled="loading" :data-chat="c.id" @click="open(c)"><img :src="c.avatar||asset(c.status==='waiting'?'01-brand-scenes/envelope-avatar':'05-avatars/avatar-placeholder')" alt=""><span class="chat-row-text"><strong>{{c.remark||c.displayName}} <Transition name="inbox-toggle"><i v-if="c.pinned" :aria-label="tr('Pinned')">⌁</i></Transition></strong><span>{{c.status==='waiting'?tr('Your letter is on its way'):c.lastMessage||tr('A little story for you')}}</span></span><span class="chat-row-end"><small>{{c.updatedAt?new Date(c.updatedAt).toLocaleDateString(locale==='ko'?'ko-KR':'en-US',{month:'short',day:'numeric'}):''}}</small><small v-if="c.status==='waiting'" class="pending-dot">{{tr("Awaiting reply")}}</small><b v-else-if="c.unreadCount" :aria-label="tr('Unread')">{{c.unreadCount}}</b><Transition name="inbox-toggle"><i v-if="c.muted" :aria-label="tr('Muted')">♧</i></Transition></span></button><button class="conversation-options" :data-options="c.id" :aria-label="`${tr('Conversation options')} · ${c.displayName}`" @click="options=c;remark=c.remark||''">•••</button></div></TransitionGroup>
<div v-if="!shown.length&&!loading&&!error" class="feature-empty"><img :src="asset('01-brand-scenes/envelope')" alt=""><h3>{{tr(hidden?'No hidden conversations.':tab==='friends'?'Your circle is just beginning.':query?'No conversations found.':'Your inbox is waiting for a little hello.')}}</h3><p>{{tr(tab==='friends'?'Follow a conversation to keep it close.':hidden?'Conversations you hide will appear here.':'Every little story begins with a letter.')}}</p></div>
<button v-if="hasMore" class="text-button" :disabled="loading" @click="load(true)">{{tr("Load more conversations")}}</button><button v-if="query" class="text-button" @click="draftQuery='';search()">{{tr("Clear search")}}</button>
<Transition name="collect-strip"><div v-if="notificationOff&&!dismissed&&!hidden" class="inbox-notification-prompt"><span>♧</span><p>{{tr("Keep up with replies")}}</p><button @click="enable">{{tr("Enable")}}</button><button :aria-label="tr('Dismiss notification reminder')" @click="dismiss">×</button></div></Transition>
</template></div>
<Transition name="d11-chat"><ChatFlow v-if="detail" :key="detail.id" :token="token" :conversation="detail" @close="detail=undefined;load()" @collect="load().then(()=>prepare())" /></Transition>
<ReplyTopup v-if="topup" :balance="balance" :token="token" :user-id="userId" :required="cost" @back="returnToReply()" @funded="returnToReply(true)" />
<Transition name="reply-receipt"><p v-if="replyState==='reply-paid'" class="d1-receipt" role="status">{{tr("Reply collected ·")}} {{collectedCost}} {{tr("diamonds")}}</p></Transition>
<div class="inbox-home-indicator" aria-hidden="true"></div><nav class="inbox-nav"><button @click="emit('close')"><img :src="asset('09-navigation-system/tab-discover-inactive')" alt="">{{tr("Home")}}</button><button aria-current="page"><img :src="asset('09-navigation-system/tab-messages-active')" alt="">{{tr("Messages")}}</button><button @click="emit('profile')"><img :src="asset('09-navigation-system/tab-profile-inactive')" alt="">{{tr("Profile")}}</button></nav>
<Transition name="inbox-drawer"><div v-if="drawer" class="inbox-drawer-overlay" @click.self="drawer=false"><aside class="inbox-drawer" role="dialog" aria-modal="true" :aria-label="tr('Inbox tools')"><div class="drawer-heading"><h2>{{tr("Inbox tools")}}</h2><button :aria-label="tr('Close inbox menu')" @click="drawer=false">×</button></div><form @submit.prevent="search"><input id="inbox-drawer-search" v-model="draftQuery" class="search-field" :aria-label="tr('Search conversations')" :placeholder="tr('Search conversations')"><button id="drawer-search" class="drawer-search-button">{{tr("Search")}}</button></form><div class="drawer-menu-group"><button id="blocked-people" class="menu-row" @click="loadBlocks">{{tr("Blocked people")}} <span>›</span></button><button class="menu-row" @click="hidden=true;detail=undefined;drawer=false">{{tr("Hidden conversations")}} <span>›</span></button><button class="menu-row" @click="tab='friends';hidden=false;drawer=false">{{tr("Following")}} <span>›</span></button></div><div class="drawer-bottom"><button class="menu-row" @click="readAll">{{tr("✓ Mark all as read")}}</button><button class="menu-row" @click="enable">{{tr("Notification settings")}} <span>›</span></button></div></aside></div></Transition>
<Transition name="inbox-sheet"><div v-if="options||payment" class="inbox-veil" :class="{'d1-payment-overlay':payment}" @click.self="closeOverlay"><section class="inbox-sheet" role="dialog" aria-modal="true" :aria-label="tr(payment?(balance<cost?'Not enough diamonds':'Collect one reply?'):'Conversation options')"><header><h2>{{tr(payment?(balance<cost?'Not enough diamonds':'Collect one reply?'):'Conversation options')}}</h2><button :disabled="busy" :aria-label="tr('Close dialog')" @click="closeOverlay">×</button></header><template v-if="payment"><div class="d1-payment-symbol"><img :src="asset('01-brand-scenes/diamond')" alt=""></div><p>{{tr(balance<cost?`Collecting one reply costs ${cost} diamonds.`:cost?'Your 10 free replies for today have been used. Pay only for this one reply.':'This reply is within your daily free allowance.')}}</p><div class="payment-summary"><div>{{tr("Total")}} <strong>{{cost}} {{tr("diamonds")}}</strong></div><div>{{tr("Your balance")}} <strong>{{balance}} {{tr("diamonds")}}</strong></div><div>{{tr(balance<cost?'Still needed':'Balance after payment')}} <strong>{{tr(Math.abs(balance-cost))}} {{tr("diamonds")}}</strong></div></div><p v-if="topupNotice" role="status">{{tr(topupNotice)}}</p><p v-if="balance<cost" role="alert">{{tr("Not enough diamonds. Your reply stays safely in the queue.")}}</p><button v-if="balance<cost" id="reply-topup" class="primary" @click="payment=false;topup=true;replyState='reply-topup'">{{tr("Get diamonds")}}</button><button id="confirm-reply-payment" class="primary" :disabled="busy||balance<cost" @click="collect">{{tr(busy?'Collecting…':`Collect reply · ${cost} diamonds`)}}</button><button id="reply-payment-cancel" class="text-button" :disabled="busy" @click="payment=false;replyState='reply-cancelled'">{{tr("Not now")}}</button></template><template v-else-if="options"><button id="option-pin" class="menu-row" :disabled="busy" @click="patch(options,{pinned:!options.pinned})">{{tr(options.pinned?'Unpin conversation':'Pin conversation')}}</button><button class="menu-row" :disabled="busy||loading" @click="options && open(options).then(()=>{options=undefined;detail=undefined})">{{tr("Mark as read")}}</button><button id="option-mute" class="menu-row" :disabled="busy" @click="patch(options,{muted:!options.muted})">{{tr(options.muted?'Unmute conversation':'Mute conversation')}}</button><button class="menu-row" :disabled="busy" @click="patch(options,{following:!options.following})">{{tr(options.following?'Unfollow conversation':'Follow conversation')}}</button><form @submit.prevent="patch(options!,{remark})"><label>{{tr("Remark")}}<input v-model="remark" maxlength="60" :aria-label="tr('Remark')"></label><button class="text-button" :disabled="busy">{{tr("Save remark")}}</button></form><button id="option-hide" class="menu-row" :disabled="busy" @click="patch(options,{hidden:!options.hidden})">{{tr(options.hidden?'Restore conversation':'Hide conversation')}}</button></template><p v-if="error" role="alert">{{tr(error)}}</p></section></div></Transition>
</section>
</template>
<style src="../inbox.css"></style>

<style scoped>
.d3-blocked{position:absolute;inset:44px 0 72px;z-index:12;background:#101e17;padding:8px 22px 24px;overflow:auto;animation:d3-list-in .25s ease-out}.d3-blocked header{display:flex;align-items:center;justify-content:space-between;margin-bottom:28px}.d3-blocked h1{font-size:18px;font-weight:500}.d3-blocked header button{font-size:30px;color:#b8ccb0;background:none;border:0}.d3-blocked-row{display:flex;align-items:center;gap:12px;border-bottom:1px solid #ffffff08;padding:18px 0;font-size:13px}.d3-blocked-row img{width:42px;height:42px;border-radius:50%;object-fit:cover}.d3-blocked-row span{flex:1;overflow-wrap:anywhere}.d3-blocked-row button{font-size:11px;padding:8px 14px;border:1px solid #b5fa7040;border-radius:18px;color:#c5d7b8;background:none}.d3-blocked .feature-empty img{width:40px;height:40px;margin:70px auto 20px}@keyframes d3-list-in{from{opacity:0;transform:translateX(18px)}to{opacity:1;transform:translateX(0)}}
</style>
